.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-md); height:var(--p-icon-md); flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:var(--p-size-md-plus); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:var(--p-space-3xs) var(--p-space-xs-plus); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius-full); background:var(--p-soft); color:var(--p-ink); font-size:var(--p-text-label); line-height:var(--p-leading-normal); font-weight:var(--p-weight-semibold); }
.ds .ds-badge[data-tone="success"] { background:var(--p-success-soft); border-color:var(--p-success-line); color:var(--p-success); }
.ds .ds-badge[data-tone="error"] { background:var(--p-error-soft); border-color:var(--p-error-line); color:var(--p-error); }
.ds .ds-badge[data-tone="warning"] { background:var(--p-warning-soft); border-color:var(--p-warning-line); color:var(--p-warning); }
/* looks: tone keeps the color, look changes the shape */
.ds .ds-badge[data-look="icon"] { gap:var(--p-space-3xs); padding-left:var(--p-space-xs); }
.ds .ds-badge[data-look="icon"] .ui-icon { width:var(--p-icon-2xs); height:var(--p-icon-2xs); stroke-width:var(--p-icon-stroke-heavy); }
/* count: a number pinned to the icon corner, so nobody opens the box to count what piled up */
.ds .ds-badge[data-look="count"] { position:relative; display:inline-grid; place-items:center; width:var(--p-control-size-sm); height:var(--p-control-size-sm); padding:0; border:0; background:transparent; color:var(--p-ink); }
.ds .ds-badge[data-look="count"] .ui-icon { width:var(--p-icon-xl); height:var(--p-icon-xl); }
.ds .ds-badge-count { position:absolute; top:var(--p-space-4xs); right:0; display:inline-grid; place-items:center; min-width:var(--p-size-md-plus); height:var(--p-size-md-plus); padding:0 var(--p-space-3xs); border-radius:var(--p-radius-full); background:var(--p-accent); color:var(--p-on-accent); box-shadow:0 0 0 var(--p-border-width-strong) var(--p-bg); font-size:var(--p-text-label); font-weight:var(--p-weight-bold); line-height:var(--p-leading-none); font-variant-numeric:tabular-nums; }

import React from 'react';
// The count look pins how many new items wait on the icon (children); the number is read as "새 알림 N개" and hides at zero.
export function Badge({ children, tone = 'neutral', look, count, ...props }) {
  if (look === 'count') return <span role="img" aria-label={count > 0 ? `새 알림 ${count}개` : '새 알림 없음'} {...props} className="ds-badge" data-tone={tone} data-look="count">{children}{count > 0 && <span className="ds-badge-count" aria-hidden="true">{count > 99 ? '99+' : count}</span>}</span>;
  return <span {...props} className="ds-badge" data-tone={tone} data-look={look}>{children}</span>;
}

